.message-body img:not(.msg-img-thumb img, .ig-result-card img, .imagegen-card img, .ig-batch-slot img, .rf-img-tile img){max-width:300px;max-height:200px;border-radius:var(--radius-sm);margin-bottom:8px;border:1px solid var(--border);cursor:pointer;transition:opacity .2s}.message-body img:not(.msg-img-thumb img, .ig-result-card img, .imagegen-card img, .ig-batch-slot img, .rf-img-tile img):hover{opacity:0.85}
.md-content{font-family:var(--md-sans);font-size:14.5px;line-height:1.75;letter-spacing:0.005em;color:var(--text-primary);contain:layout style;overflow-x:hidden;max-width:100%;overflow-wrap:break-word;word-wrap:break-word}.md-content p{margin-bottom:13px}.md-content p:last-child{margin-bottom:0}.md-content strong{font-weight:650}.md-content em{font-style:italic;color:var(--text-secondary)}.md-content a{color:var(--accent);text-decoration:none;word-break:break-word;text-underline-offset:2px}.md-content a:hover{text-decoration:underline}.md-content ul,.md-content ol{margin:10px 0 13px 22px}.md-content li{margin-bottom:5px}.md-content li::marker{color:var(--text-tertiary)}.md-content h1,.md-content h2,.md-content h3,.md-content h4{margin:22px 0 9px;font-weight:650;letter-spacing:-0.01em;line-height:1.35}.md-content h1{font-size:20px}.md-content h2{font-size:17px}.md-content h3{font-size:15px}.md-content blockquote{border-left:3px solid var(--accent);padding:8px 16px;margin:12px 0;color:var(--text-secondary);background:var(--bg-tertiary);border-radius:0 var(--radius-xs) var(--radius-xs) 0}.md-content code{font-family:'JetBrains Mono',monospace;font-size:12.5px;background:var(--bg-tertiary);padding:2px 6px;border-radius:4px;border:1px solid var(--border)}.md-content pre{margin:12px 0;border-radius:var(--radius-sm);overflow:hidden;border:1px solid var(--border)}.md-content pre code{display:block;padding:16px;overflow-x:auto;background:var(--bg-secondary);border:none;line-height:1.5}.code-header{display:flex;align-items:center;gap:8px;padding:6px 12px;background:var(--bg-tertiary);border-bottom:1px solid var(--border);font-size:11px;font-family:'JetBrains Mono',monospace;color:var(--text-tertiary)}.code-header span{flex:1}.copy-btn{background:none;border:none;color:var(--text-tertiary);cursor:pointer;font-size:11px;font-family:inherit;padding:2px 8px;border-radius:4px;transition:color var(--transition),background-color var(--transition);flex-shrink:0}.copy-btn:hover{color:var(--text-primary);background:var(--bg-hover)}.md-content.user-content{white-space:pre-wrap;word-break:break-word}pre.code-long{position:relative}pre.code-long[data-collapsed="true"]>code{max-height:200px;overflow:hidden}pre.code-long[data-collapsed="true"]::after{content:'';position:absolute;bottom:0;left:0;right:0;height:60px;background:linear-gradient(to bottom,transparent,var(--bg-secondary));pointer-events:none;border-radius:0 0 var(--radius-sm) var(--radius-sm)}.code-collapse-btn{background:none;border:none;color:var(--accent);cursor:pointer;font-size:11px;font-family:'JetBrains Mono',monospace;padding:2px 8px;border-radius:4px;transition:color var(--transition),background-color var(--transition);flex-shrink:0;white-space:nowrap}.code-collapse-btn:hover{background:var(--accent-subtle);color:var(--accent-hover)}.table-header{display:flex;align-items:center;gap:8px;padding:4px 12px;background:var(--bg-tertiary);border-bottom:1px solid var(--border);font-size:11px;font-family:'JetBrains Mono',monospace;color:var(--text-tertiary)}.table-header span{flex:1}.md-table-wrapper{overflow-x:auto;margin:12px 0;border:1px solid var(--border);border-radius:var(--radius-sm);scrollbar-width:thin;scrollbar-color:var(--text-tertiary) transparent}.md-table-wrapper::-webkit-scrollbar{height:6px}.md-table-wrapper::-webkit-scrollbar-track{background:transparent}.md-table-wrapper::-webkit-scrollbar-thumb{background:var(--text-tertiary);border-radius:3px}.md-content table{width:max-content;min-width:100%;border-collapse:collapse;font-size:13px;margin:0}.md-content th,.md-content td{padding:8px 12px;border:1px solid var(--border);text-align:left;white-space:normal;word-break:break-word}.md-content th{background:var(--bg-tertiary);font-weight:600;white-space:nowrap}
/* ★ Perf: replaced backdrop-filter:blur(10px) with solid rgba bg — blur forces GPU re-composite on every scroll frame, 
 * costing ~2-4ms per frame. Solid bg is visually identical on dark theme and costs nothing. */
.turn-nav{display:flex;flex-direction:row;align-items:center;gap:2px;min-width:0;max-width:min(52%,560px);overflow-x:auto;overflow-y:hidden;padding:3px 5px;background:rgba(17,17,21,0.96);border:1px solid var(--border);border-radius:16px;scrollbar-width:none;opacity:0.85;transition:opacity .3s;flex:0 1 auto}.turn-nav:hover{opacity:1}.turn-nav::-webkit-scrollbar{display:none}.turn-nav:empty{display:none}.turn-nav-label{font-size:8px;font-weight:700;color:var(--text-secondary);letter-spacing:.08em;text-transform:uppercase;padding:2px 0 3px;user-select:none}.turn-dot{width:26px;height:26px;border-radius:50%;background:rgba(255,255,255,0.04);border:1.5px solid var(--border);color:var(--text-secondary);font-size:9px;font-weight:700;display:flex;align-items:center;justify-content:center;cursor:pointer;transition:color .2s,background-color .2s,border-color .2s,transform .2s;font-family:'JetBrains Mono',monospace;flex-shrink:0}.turn-dot:hover{background:var(--accent-subtle);color:var(--accent);border-color:var(--accent);transform:scale(1.15)}.turn-dot.active{background:var(--accent);color:white;border-color:var(--accent)}/* ★ Perf: contain:content isolates thinking block layout from parent reflows */
.thinking-block{margin-bottom:8px;border:1px solid var(--border);border-radius:var(--radius-sm);background:transparent;overflow:hidden;contain:content}

/* Windowed messages keep their execution history available as quiet metadata,
   not as a second full-width action bar competing with the turn controls. */
.message-activity-loader{width:fit-content;max-width:100%;min-height:28px;margin:3px 0 7px;padding:4px 6px;border:0;border-radius:5px;background:transparent;color:var(--text-tertiary);font:500 11px/1.4 var(--md-sans);text-align:left;cursor:pointer;display:inline-flex;align-items:center;gap:6px;vertical-align:top;transition:background-color var(--transition),color var(--transition),opacity var(--transition)}
.message-activity-loader>svg{opacity:.62}
.message-activity-loader>span:nth-child(2){min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.message-activity-loader-chevron{font-size:14px;font-weight:400;line-height:1;color:currentColor;opacity:.38;transition:opacity var(--transition),transform var(--transition)}
.message-activity-loader:hover{background:var(--bg-hover);color:var(--text-secondary)}
.message-activity-loader:hover .message-activity-loader-chevron{opacity:.72;transform:translateX(1px)}
.message-activity-loader.is-loading{cursor:wait;opacity:.62}
.message-activity-loader.is-loading>svg{animation:spin .8s linear infinite}
.message-activity-loader.is-loading .message-activity-loader-chevron{visibility:hidden}
.message-activity-loader.is-error{color:var(--error-text);background:transparent}
.message-activity-loader.is-error:hover{background:var(--error-bg)}
.message-activity-loader:focus-visible{outline:2px solid var(--accent);outline-offset:2px}

/* Display-only "Earlier Thinking" block surfaced on Continue rollback —
   the trailing reasoning that was discarded because no provider can
   accept it on replay. Visually distinguished from live thinking via
   dashed border + slightly muted background. */
.thinking-block.thinking-prior{border-style:dashed;opacity:.85}
.thinking-block.thinking-prior .thinking-label::before{content:"\2937  ";opacity:.7}
.thinking-block.content-prior .thinking-label{color:var(--text-tertiary)}
.thinking-block.content-prior .thinking-label::before{content:"\21A9  "}
.thinking-header{display:flex;align-items:center;gap:8px;padding:6px 12px;cursor:pointer;user-select:none;transition:background var(--transition)}.thinking-header:hover{background:var(--bg-hover)}.thinking-label{font-size:12px;font-weight:500;color:var(--text-tertiary);flex:1}.thinking-toggle{font-size:11px;color:var(--text-tertiary);opacity:.6;transition:transform .3s ease}.thinking-block.expanded .thinking-toggle{transform:rotate(180deg)}.thinking-content{max-height:0;overflow:hidden;transition:max-height .4s ease}.thinking-block.expanded .thinking-content{max-height:none}.thinking-text{padding:0 14px 14px;font-size:13px;line-height:1.6;color:var(--text-secondary);white-space:pre-wrap;word-break:break-word}
/* Markdown-rendered thinking (Codex '**…**' headline summaries): the base
 * rule is white-space:pre-wrap for plain-text streaming; rendered HTML must
 * NOT pre-wrap or the newlines between tags become visible blank lines. */
.thinking-text.thinking-md{white-space:normal}
.thinking-text.thinking-md p{margin:0 0 8px}
.thinking-text.thinking-md p:last-child{margin-bottom:0}
.thinking-text.thinking-md ul,.thinking-text.thinking-md ol{margin:0 0 8px;padding-left:1.4em}
.thinking-text.thinking-md ul:last-child,.thinking-text.thinking-md ol:last-child{margin-bottom:0}
/* Typed conversation surface renders the thinking block as semantic
   <details>/<summary> reusing the same classes as the div+.expanded idiom:
   hide the UA disclosure marker, rotate the chevron and reveal the content
   off the [open] attribute instead of the .expanded class. */
summary.thinking-header{list-style:none}
summary.thinking-header::-webkit-details-marker{display:none}
.thinking-block[open] .thinking-toggle{transform:rotate(180deg)}
.thinking-block[open] .thinking-content{max-height:none}
.bilingual-block{margin-top:10px;border:1px solid var(--border);border-radius:var(--radius-sm);overflow:hidden;background:var(--bg-secondary);contain:layout style}.bilingual-original{border-color:rgba(165,180,252,0.2);background:rgba(30,27,75,0.15)}.bilingual-translated{border-color:rgba(110,86,207,0.2);background:rgba(110,86,207,0.04)}.bilingual-header{display:flex;align-items:center;gap:8px;padding:6px 12px;cursor:pointer;user-select:none;transition:background var(--transition)}.bilingual-header:hover{background:var(--bg-hover)}.bilingual-label{font-size:12px;color:var(--text-tertiary);flex:1;display:flex;align-items:center;gap:0}.bilingual-type{opacity:.5;transition:opacity .2s}.bilingual-type.active{opacity:1;color:var(--text-secondary);font-weight:600}.bilingual-sep{opacity:.3;margin:0 4px;font-size:10px}.bilingual-model{margin-left:8px;font-size:10px;font-weight:500;color:var(--accent);background:rgba(139,92,246,0.1);padding:1px 7px;border-radius:8px;font-family:'JetBrains Mono',monospace;letter-spacing:.02em;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.bilingual-toggle{font-size:10px;color:var(--text-tertiary);opacity:.5;transition:transform .3s ease}.bilingual-block.expanded .bilingual-toggle{transform:rotate(180deg)}.bilingual-body{max-height:0;overflow:hidden;transition:max-height .4s ease}.bilingual-block.expanded .bilingual-body{max-height:none}.bilingual-body .md-content{padding:0 12px 10px;font-size:13px;opacity:.85}.bilingual-copy-btn{display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;padding:0;border:none;border-radius:4px;background:transparent;color:var(--text-tertiary);cursor:pointer;opacity:.5;transition:all .2s ease;flex-shrink:0}.bilingual-copy-btn:hover{opacity:1;background:var(--bg-hover);color:var(--text-secondary)}.bilingual-copy-btn.copied{opacity:1;color:#34d399}
/* ── Live auto-translation indicator ──
 * Streams the 译文 in as it arrives, then morphs into the purple
 * bilingual block. Tinted with the same accent (139,92,246) as
 * .bilingual-* so the transition is seamless; colors lean on CSS
 * variables / low-alpha accent so they hold up on light/tofu themes. */
.translate-loading{margin-top:10px;border:1px solid var(--accent-subtle);border-radius:var(--radius-sm);background:linear-gradient(180deg,rgba(110,86,207,0.07),rgba(110,86,207,0.02));overflow:hidden;position:relative;contain:layout style}
.translate-loading::before{content:"";position:absolute;top:0;left:-40%;width:40%;height:2px;background:linear-gradient(90deg,transparent,var(--accent),transparent);animation:translate-sheen 1.8s ease-in-out infinite;opacity:.7}
@keyframes translate-sheen{0%{left:-40%}100%{left:100%}}
.translate-loading-head{display:flex;align-items:center;gap:8px;padding:9px 13px}
.translate-loading.has-preview .translate-loading-head{border-bottom:1px solid var(--accent-subtle)}
.translate-loading-label{font-size:12px;font-weight:600;letter-spacing:.02em;color:var(--accent);background:linear-gradient(90deg,var(--accent) 0%,var(--text-secondary) 50%,var(--accent) 100%);background-size:200% 100%;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;animation:translate-shimmer 2.4s linear infinite}
@keyframes translate-shimmer{to{background-position:-200% 0}}
.translate-spinner{width:13px;height:13px;border:2px solid var(--accent-subtle);border-top-color:var(--accent);border-radius:50%;animation:spin .7s linear infinite;flex-shrink:0}@keyframes spin{to{transform:rotate(360deg)}}
.translate-status-sub{font-size:11px;color:var(--thinking-text);display:flex;align-items:center;gap:4px;padding:2px 13px 8px}
.translate-preview{padding:10px 14px 12px;max-height:440px;overflow-y:auto;overscroll-behavior:contain;contain:content;animation:translate-fade-in .25s ease}
.translate-preview::-webkit-scrollbar{width:6px}.translate-preview::-webkit-scrollbar-track{background:transparent}.translate-preview::-webkit-scrollbar-thumb{background:transparent;border-radius:3px}.translate-preview:hover::-webkit-scrollbar-thumb{background:var(--border)}
@keyframes translate-fade-in{from{opacity:0;transform:translateY(-2px)}to{opacity:1;transform:none}}
