.translate-preview .md-content>:first-child{margin-top:0}.translate-preview .md-content>:last-child{margin-bottom:0}
.translate-caret{display:inline-block;width:7px;height:14px;margin-left:3px;vertical-align:text-bottom;background:var(--accent);border-radius:2px;animation:translate-blink 1s step-end infinite;box-shadow:0 0 6px var(--accent-subtle)}
@keyframes translate-blink{0%,100%{opacity:1}50%{opacity:0}}

/* ── Streaming auto-translate render UNIFICATION (2026-07-07) ──
 * During an agent task with auto-translate ON, the incremental translator's
 * Chinese-so-far renders as the PRIMARY body in the [data-zone="translatedPrimary"]
 * slot (ABOVE the English content zone) — the same role Chinese has in the
 * SETTLED bilingual view. The still-untranslated English tail (current round)
 * is DEMOTED in the content zone below, styled to read as the quiet live edge
 * of the translation rather than a competing full body. Because the streaming
 * bubble already has the settled structure, finalize is a visual no-op.
 * Understated by design: no boxes, no extra chrome — just typographic weight. */
.stream-translated-body{animation:translate-fade-in .25s ease}
.stream-translated-body .md-content{color:var(--text-primary)}
.stream-translated-body .md-content>:first-child{margin-top:0}
/* The live Chinese edge: a soft blinking caret trailing the last block. */
.stream-translated-body .md-content>:last-child::after{content:"";display:inline-block;width:6px;height:1em;margin-left:3px;vertical-align:text-bottom;background:var(--accent);border-radius:2px;opacity:.75;animation:translate-blink 1s step-end infinite}
/* English tail: demoted to a quiet, smaller, dimmed continuation directly
 * under the Chinese — no separator box, so the two read as one flowing body
 * that is converging to Chinese round-by-round. */
.stream-content-demoted{margin-top:2px}
.stream-content-demoted .md-content{font-size:12.5px;color:var(--text-tertiary);opacity:.72;transition:opacity .3s ease}
.stream-content-demoted .md-content>:first-child{margin-top:0}
/* Finalize handoff: the closing round's English is hidden the instant the
 * worker starts assembling the final Chinese, so it never doubles. */
.stream-content-tail-hidden{display:none}

/* Send-path auto-translate failed → original text was sent. Quiet amber pill
   under the user bubble; clicking it retranslates just that message. */
.translate-failed-notice{display:inline-flex;align-items:center;gap:7px;margin-top:8px;padding:5px 11px;font-size:11.5px;line-height:1.3;color:#fbbf24;background:rgba(245,158,11,0.08);border:1px solid rgba(245,158,11,0.22);border-radius:999px;cursor:pointer;user-select:none;transition:background .2s ease,border-color .2s ease}
.translate-failed-notice:hover{background:rgba(245,158,11,0.14);border-color:rgba(245,158,11,0.4)}
.translate-failed-notice .tfn-icon{flex-shrink:0;opacity:.9}
.translate-failed-notice .tfn-text{opacity:.92}
.translate-failed-notice .tfn-retry{margin-left:2px;padding-left:8px;border-left:1px solid rgba(245,158,11,0.3);font-weight:600;opacity:.85}
.translate-failed-notice:hover .tfn-retry{opacity:1;text-decoration:underline}
/* Display-translation terminal failure (assistant / critic / VU bubble): a
   quiet borderless inline retry line — no filled pill, no box, matching the
   "just typographic weight" understatement of the translate family. Muted
   tertiary text at rest; lifts to the accent color + spins its glyph on
   hover/focus to read as "click to retry". The full upstream error (429/402
   quota etc.) sits on the title tooltip. */
.translate-retry-line{display:inline-flex;align-items:center;gap:6px;margin-top:7px;font-size:11.5px;line-height:1.3;color:var(--text-tertiary);cursor:pointer;user-select:none;border-radius:var(--radius-sm);transition:color .18s ease}
.translate-retry-line:hover,.translate-retry-line:focus-visible{color:var(--accent);outline:none}
.translate-retry-line .trl-icon{flex-shrink:0;display:block;opacity:.75;transition:opacity .18s ease,transform .5s ease}
.translate-retry-line:hover .trl-icon,.translate-retry-line:focus-visible .trl-icon{opacity:1;transform:rotate(-180deg)}
.translate-retry-line .trl-text{opacity:.9}
.translate-retry-line:hover .trl-text{text-decoration:underline;text-underline-offset:2px}
/* Subtle inline translating indicator on user message — replaces the old separate ✨ bubble */
@keyframes translatePulse{0%,100%{opacity:.4}50%{opacity:1}}
/* ★ Perf: content-visibility:auto on search blocks — off-screen blocks skip layout/paint.
 * contain-intrinsic-size provides estimated height to preserve scrollbar accuracy. */
.search-result-item{padding:10px 14px;border-top:1px solid rgba(59,130,246,0.1);transition:background var(--transition)}.search-result-item:hover{background:rgba(59,130,246,0.04)}.search-result-title{font-size:13px;font-weight:600;color:#93c5fd;display:flex;align-items:center;gap:6px;flex-wrap:wrap}.search-result-title a{color:#93c5fd;text-decoration:none}.search-result-title a:hover{text-decoration:underline;color:#bfdbfe}.search-result-source{font-size:10px;color:var(--text-tertiary);padding:1px 6px;background:var(--bg-tertiary);border-radius:4px;font-family:'JetBrains Mono',monospace}.search-result-snippet{font-size:12px;color:var(--text-secondary);margin-top:4px;line-height:1.5;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.search-result-url{font-size:10px;color:var(--text-tertiary);margin-top:3px;font-family:'JetBrains Mono',monospace;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.search-result-fetched{font-size:9px;color:#34d399;background:rgba(52,211,153,0.1);padding:1px 6px;border-radius:4px;font-family:'JetBrains Mono',monospace;margin-left:4px;white-space:nowrap}.search-result-fetched.pdf{color:#f59e0b;background:rgba(245,158,11,0.1)}

/* ── Vertical-domain card (HF Papers / Semantic Scholar / arXiv / etc.) ── */
