/* Paper correction, progressive recommendation, and first-open placeholders.
 * This late section intentionally follows the main paper surface: it reuses
 * its layout/keyframes while keeping the source modules below the 100 KiB
 * model-readable ownership budget. */

/* ── Correction banner (false-premise) ── */
.paper-correction{display:flex;gap:12px;padding:14px 16px;border:1px solid var(--warn,#d9922e);border-radius:14px;background:color-mix(in srgb,var(--warn,#d9922e) 8%,transparent)}
.paper-correction-icon{flex:0 0 auto;color:var(--warn,#d9922e);margin-top:1px}
.paper-correction-body{flex:1;min-width:0;display:flex;flex-direction:column;gap:6px}
.paper-correction-title{font-size:13px;font-weight:700;color:var(--text-primary)}
.paper-correction-note{font-size:12.5px;color:var(--text-secondary);line-height:1.55}
.paper-correction-offer{margin-top:6px;background:var(--bg-tertiary)}
.paper-correction-offer-label{font-size:11px;font-weight:600;color:var(--warn,#d9922e);text-transform:uppercase;letter-spacing:.03em}

/* ── Streaming describe-to-recommend (progressive reveal, aligned with chatInner) ── */
/* Status line above the list: interpreting → grounding progress. */
.paper-rec-status{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--text-tertiary);min-height:18px}
.paper-rec-status[hidden]{display:none}
/* Research tool timeline in the recommend view reuses .paper-report-tools
   (chatInner's unified panel), but the recommend shell is a centered flex
   column with its own gap/padding — neutralize the report-flex insets so the
   panel aligns with the status line + cards. */
.paper-rec-tools{padding:0;flex-shrink:1}
.paper-rec-tools:empty,.paper-rec-tools[hidden]{display:none}
.paper-rec-spin{flex:0 0 auto;width:13px;height:13px;border:2px solid var(--border);border-top-color:var(--accent);border-radius:50%;animation:paperSpin .8s linear infinite}
.paper-rec-banner:empty{display:none}
/* A card streams in: opacity+translateY only (compositor-only, no reflow),
   staggered by its --i index. animation-fill-mode:both prevents a pre-flash. */
.paper-rec-card[data-status="grounded"]{animation:paperRecIn .34s cubic-bezier(.2,.9,.3,1.1) both;animation-delay:calc(var(--i,0) * 55ms)}
@keyframes paperRecIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
/* Skeleton placeholder — same box as a real card so the swap causes zero CLS. */
.paper-rec-skeleton{cursor:default;pointer-events:none;border-style:dashed}
.paper-rec-skeleton:hover{border-color:var(--border);transform:none;box-shadow:none}
.paper-rec-sk-num{background:var(--bg-hover)}
.paper-rec-sk-line{height:11px;border-radius:6px;background:linear-gradient(90deg,var(--bg-hover) 25%,var(--border) 37%,var(--bg-hover) 63%);background-size:200% 100%;animation:paperRecShimmer 1.3s ease-in-out infinite}
.paper-rec-sk-title{width:70%;height:13px}
.paper-rec-sk-why{width:88%}
.paper-rec-sk-meta{width:40%;margin-top:3px}
@keyframes paperRecShimmer{to{background-position:-200% 0}}
/* First-open chat skeleton (epic ②) — placeholder bubbles shown INSTANTLY when
   opening a not-yet-loaded conversation, swapped out zero-CLS when the real
   messages arrive. Reuses the paperRecShimmer keyframe. The `.message` /
   `.message-content` structure is inherited from the real bubble styles so the
   swap causes no layout jump. */
.chat-skeleton{pointer-events:none}
.chat-sk-avatar{width:100%;height:100%;border-radius:50%;background:linear-gradient(90deg,var(--bg-hover) 25%,var(--border) 37%,var(--bg-hover) 63%);background-size:200% 100%;animation:paperRecShimmer 1.3s ease-in-out infinite}
.chat-sk-line{height:12px;margin:7px 0;border-radius:6px;background:linear-gradient(90deg,var(--bg-hover) 25%,var(--border) 37%,var(--bg-hover) 63%);background-size:200% 100%;animation:paperRecShimmer 1.3s ease-in-out infinite}
@media (prefers-reduced-motion:reduce){.chat-sk-avatar,.chat-sk-line{animation:none}}
/* Respect reduced-motion: no shimmer, no stagger, no slide — reveal instantly. */
@media (prefers-reduced-motion:reduce){
  .paper-rec-card[data-status="grounded"]{animation:none}
  .paper-rec-sk-line{animation:none}
  .paper-rec-spin{animation-duration:1.6s}
  /* Reading surface: kill decorative motion but keep the (instant) progress
   * fill legible — the read-time bar still conveys position, just without the
   * animated width tween; the section chips stop pulsing; the landing icon
   * stops floating. Spinners keep spinning (they signal in-progress work). */
  .paper-read-time-fill{transition:none}
  .report-section-chip.running .report-section-chip-dot{animation:none}
  .paper-landing-icon{animation:none}
}
/* Paper loading/error states and the responsive single-pane reader layout. */
.paper-loading{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:40px;color:var(--text-secondary);font-size:13px}
.paper-loading-spinner{width:28px;height:28px;border:3px solid var(--border);border-top-color:var(--accent);border-radius:50%;animation:paperSpin .8s linear infinite}
@keyframes paperSpin{to{transform:rotate(360deg)}}
.paper-fetch-progress{max-width:420px;margin:0 auto;width:100%;text-align:center}
.paper-fetch-title{color:var(--text-primary);font-weight:500;font-size:13px}
.paper-fetch-id{color:var(--text-tertiary);font-weight:400;font-size:12px;margin-left:6px;font-family:var(--font-mono,monospace)}
.paper-fetch-bar-wrap{width:100%;height:4px;background:var(--border);border-radius:2px;overflow:hidden;margin-top:4px}
.paper-fetch-bar{height:100%;background:var(--accent);border-radius:2px;transition:width .15s ease}
.paper-fetch-detail{color:var(--text-tertiary);font-size:12px;font-variant-numeric:tabular-nums}
@keyframes paperProgressIndet{0%{margin-left:-40%}100%{margin-left:100%}}
.paper-error{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:40px;color:var(--text-tertiary);font-size:13px;text-align:center}
.paper-error-detail{font-size:12px;color:var(--text-secondary);max-width:560px;word-break:break-word;font-family:var(--font-mono,monospace)}
.paper-retry-btn{margin-top:8px;padding:8px 20px;border:1px solid var(--border);border-radius:8px;background:var(--bg-hover);color:var(--text-primary);font-size:12px;font-weight:600;cursor:pointer;transition:all .15s;font-family:inherit}
.paper-retry-btn:hover{background:var(--bg-tertiary);border-color:var(--border-light)}

/* On phones and coarse-pointer portrait tablets, a side-by-side PDF/reader
 * would make both panes unusable. The JS matchMedia owner mirrors this exact
 * predicate and writes data-paper-view; these rules only project that state. */
@media(max-width:768px),(max-width:1024px) and (pointer:coarse){
  /* Reserve the fixed switcher plus the platform safe area. */
  .paper-mode-container{--paper-switch-h:calc(54px + env(safe-area-inset-bottom,0px))}
  .paper-body{position:relative;flex-direction:row;padding-bottom:var(--paper-switch-h)}
  /* Both panes overlay the same area. !important clears stale widths left by
   * a desktop divider drag before a viewport/orientation transition. */
  .paper-left,.paper-right{position:absolute!important;inset:0;width:auto!important;max-width:none!important;min-width:0!important;flex:none!important;border:none!important}
  .paper-body[data-paper-view="pdf"] .paper-left{display:flex;z-index:2}
  .paper-body[data-paper-view="pdf"] .paper-right{display:none}
  .paper-body[data-paper-view="reader"] .paper-right{display:flex;z-index:2}
  .paper-body[data-paper-view="reader"] .paper-left{display:none}
  .paper-divider{display:none}

  .paper-mobile-switch{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:25;height:var(--paper-switch-h);padding-bottom:env(safe-area-inset-bottom,0px);background:var(--bg-secondary);border-top:1px solid var(--border);box-shadow:0 -2px 12px rgba(0,0,0,0.12)}
  .paper-mobile-switch-btn{flex:1;display:flex;align-items:center;justify-content:center;gap:7px;border:none;background:none;color:var(--text-tertiary);font-family:inherit;font-size:13px;font-weight:600;cursor:pointer;-webkit-tap-highlight-color:transparent;border-top:2px solid transparent;transition:color .15s,background .15s}
  .paper-mobile-switch-btn svg{flex-shrink:0}
  .paper-mobile-switch-btn.active{color:var(--accent);background:var(--bg-hover);border-top-color:var(--accent)}

  .paper-pdf-toolbar{padding:4px 8px}
  /* In reading mode the drawer remains the paper library, rather than falling
   * back to the chat conversation list when the viewport becomes narrow. */
  .sidebar.paper-active .paper-sidebar-overlay{display:flex!important}
  .sidebar.paper-active .sidebar-action-row,
  .sidebar.paper-active .sidebar-search-wrapper,
  .sidebar.paper-active .folder-quickadd,
  .sidebar.paper-active .sidebar-body,
  .sidebar.paper-active .conversations-list{display:none!important}
  .sidebar.paper-active .sidebar-header h1{display:none!important}
  .paper-sidebar-current{padding:14px 16px}
  .paper-sidebar-new-inline-btn{width:32px;height:32px}
  .paper-lib-item{padding:12px;min-height:48px}
  .paper-lib-item-del{display:flex;width:32px;height:32px}
  .paper-tab-btn{padding:10px 6px;font-size:12px;gap:4px}
  .paper-tab-btn svg{width:13px;height:13px}
  .paper-qa-input-area{padding:8px}
  #paperQAInput{font-size:16px}
  .paper-report-content{padding:14px}
  .paper-landing{padding:24px 16px}
