.ig-mode-edit .ptool-icon{color:#22d3ee}
.ig-mode-generate .ptool-icon{color:#e879f9}
/* Before → after strip for image edits */
.ig-beforeafter{display:flex;align-items:center;gap:10px;padding:12px;background:linear-gradient(135deg,rgba(34,211,238,0.05),rgba(34,211,238,0.02))}
.ig-ba-item{flex:1 1 0;min-width:0;margin:0;display:flex;flex-direction:column;align-items:center;gap:6px}
.ig-ba-item img{display:block;width:100%;height:auto;max-height:340px;object-fit:contain;border-radius:8px;border:1px solid var(--border);cursor:zoom-in;transition:filter .2s,transform .2s;background:var(--bg-secondary)}
