.sw-a-done .sw-a-role-tag,.sw-a-completed .sw-a-role-tag{background:rgba(74,222,128,0.08);border-color:rgba(74,222,128,0.20);color:#86efac}
.sw-a-failed .sw-a-role-tag,.sw-a-error .sw-a-role-tag{background:rgba(248,113,113,0.08);border-color:rgba(248,113,113,0.20);color:#fca5a5}
.sw-a-id{font-size:10px;padding:1px 6px;border-radius:6px;font-family:'JetBrains Mono',monospace;color:var(--text-tertiary);background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.06);cursor:copy;flex-shrink:0;letter-spacing:0.02em;transition:all .15s}
.sw-a-id:hover{color:var(--text-secondary);background:rgba(255,255,255,0.07);border-color:rgba(255,255,255,0.12)}
