.sw-a-model{font-size:10px;padding:1px 7px;border-radius:6px;font-family:'JetBrains Mono',monospace;font-weight:500;color:var(--text-secondary);background:rgba(167,139,250,0.10);border:1px solid rgba(167,139,250,0.22);flex-shrink:0;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
