.sw-a-failed .sw-a-phase-pill,.sw-a-error .sw-a-phase-pill{color:#f87171;background:rgba(248,113,113,0.08)}
.sw-a-timer{font-size:10px;color:var(--text-tertiary);font-family:'JetBrains Mono',monospace;flex-shrink:0}
.sw-a-chevron{font-size:10px;color:var(--text-tertiary);transition:transform .15s;flex-shrink:0}
/* Agent card body (collapsible) */
