.sw-agent.sw-a-open .sw-a-body{display:block}
.sw-agent.sw-a-open .sw-a-chevron{transform:rotate(180deg)}
.sw-a-objective{font-size:11px;color:var(--text-secondary);line-height:1.5;margin-bottom:6px;padding:6px 8px;background:rgba(255,255,255,0.02);border-radius:6px;border-left:2px solid rgba(251,191,36,0.3);white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word}
.sw-a-done .sw-a-objective,.sw-a-completed .sw-a-objective{border-left-color:rgba(74,222,128,0.3)}
.sw-a-failed .sw-a-objective,.sw-a-error .sw-a-objective{border-left-color:rgba(248,113,113,0.3)}
/* Agent tool chain */
.sw-a-tools{display:flex;align-items:center;gap:4px;flex-wrap:wrap;margin-bottom:6px}
.sw-a-tool-tag svg,.sw-dep-tag svg{display:block}
.sw-a-tool-tag{display:inline-flex;align-items:center;gap:3px;padding:2px 6px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.06);border-radius:4px;font-family:'JetBrains Mono',monospace;font-size:9px;color:var(--text-tertiary)}
/* ── Per-agent execution timeline ── */
.sw-a-timeline{display:flex;flex-direction:column;gap:2px;margin:6px 0;padding:6px 8px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.05);border-radius:6px}
.sw-tl-row{font-size:10px;font-family:'JetBrains Mono',monospace;color:var(--text-secondary)}
.sw-tl-line{display:flex;align-items:center;gap:6px;padding:3px 4px;border-radius:4px;transition:background .12s}
.sw-tl-expandable .sw-tl-line{cursor:pointer}
.sw-tl-expandable:hover .sw-tl-line{background:rgba(255,255,255,0.04)}
.sw-tl-dot{display:inline-flex;align-items:center;justify-content:center;width:10px;height:10px;border-radius:50%;font-size:8px;flex-shrink:0;color:#fff;font-weight:700}
.sw-tl-running{background:rgba(251,191,36,0.55);box-shadow:0 0 0 2px rgba(251,191,36,0.15);animation:swTlPulse 1.2s ease-in-out infinite}
.sw-tl-done{background:rgba(74,222,128,0.6)}
.sw-tl-dot svg{width:7px;height:7px}
.sw-tl-failed{background:rgba(248,113,113,0.6)}
@keyframes swTlPulse{0%,100%{opacity:1}50%{opacity:0.45}}
.sw-tl-icon{font-size:10px;opacity:0.85;flex-shrink:0}
.sw-tl-name{color:var(--text-primary);font-weight:500;flex-shrink:0}
.sw-tl-args{color:var(--text-tertiary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0;flex:1}
.sw-tl-elapsed{color:var(--text-tertiary);font-size:9px;flex-shrink:0;margin-left:auto}
.sw-tl-chev{color:var(--text-tertiary);font-size:9px;transition:transform .15s;flex-shrink:0}
.sw-tl-row.sw-tl-open .sw-tl-chev{transform:rotate(180deg)}
.sw-tl-detail{display:none;margin:4px 6px 2px 22px;padding:6px 8px;background:rgba(0,0,0,0.18);border-left:2px solid rgba(255,255,255,0.1);border-radius:4px;font-family:'JetBrains Mono',monospace;font-size:10px;color:var(--text-secondary);white-space:pre-wrap;word-break:break-word;max-height:200px;overflow-y:auto}
.sw-tl-row.sw-tl-open .sw-tl-detail{display:block}
.sw-tl-detail-error{border-left-color:#f87171;color:#fca5a5}
.sw-tl-omitted,.sw-tl-truncated{font-family:'JetBrains Mono',monospace;font-size:9px;color:var(--text-tertiary)}
.sw-tl-omitted{padding:2px 4px;border-bottom:1px dashed rgba(255,255,255,0.08)}
.sw-tl-truncated{margin-top:5px;padding-top:5px;border-top:1px dashed rgba(255,255,255,0.08)}
/* Agent output preview */
.sw-a-preview{font-size:11px;color:var(--text-secondary);line-height:1.5;margin-bottom:6px;padding:8px;background:rgba(255,255,255,0.02);border-radius:6px;border:1px solid rgba(255,255,255,0.04);max-height:220px;overflow-y:auto;overscroll-behavior:contain;white-space:pre-wrap;word-break:break-word}
.sw-a-err{font-size:10px;color:#f87171;font-family:'JetBrains Mono',monospace;padding:4px 8px;background:rgba(248,113,113,0.05);border-radius:4px;margin-bottom:6px}
.sw-a-meta{display:flex;align-items:center;gap:10px;font-size:10px;font-family:'JetBrains Mono',monospace;color:var(--text-tertiary)}
/* ── Footer stats ── */
.sw-footer{display:flex;align-items:center;gap:12px;padding:10px 18px;border-top:1px solid rgba(251,191,36,0.08);font-size:10px;font-family:'JetBrains Mono',monospace;color:var(--text-tertiary)}
.sw-complete .sw-footer{border-top-color:rgba(74,222,128,0.08)}
.sw-footer-sep{color:var(--text-tertiary);opacity:0.3}
/* ── Swarm init (pre-agent-list) ── */
.sw-spinner{width:16px;height:16px;border:2px solid rgba(251,191,36,0.2);border-top-color:#fbbf24;border-radius:50%;animation:spin .8s linear infinite;margin-left:auto}
/* ── Async swarm: "running in background" pill on the panel header ─────────── */
/*    Shown when the panel is no longer the active tool round but agents are   */
/*    still working — gives the user a quiet "still cooking" indicator.        */
.sw-status-pill.sw-pill-async{color:#fbbf24;background:rgba(251,191,36,0.08);border:1px solid rgba(251,191,36,0.18)}
.sw-status-pill.sw-pill-async .sw-async-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#fbbf24;margin-right:4px;animation:swAsyncDot 1.4s ease-in-out infinite}
@keyframes swAsyncDot{0%,100%{opacity:.35;transform:scale(.85)}50%{opacity:1;transform:scale(1.15)}}
/* ── Stale pill: a swarm panel that never received its completion signal ── */
/*    (server restart / dropped SSE). Muted slate — reads as 'unconfirmed',   */
/*    distinct from running (blue), async (amber), done (green), error (red).  */
.sw-status-pill.sw-pill-stale{color:#94a3b8;background:rgba(148,163,184,0.10);border:1px solid rgba(148,163,184,0.20)}
[data-theme="light"] .sw-status-pill.sw-pill-stale{color:#64748b;background:rgba(100,116,139,0.10)}
[data-theme="tofu"] .sw-status-pill.sw-pill-stale{color:#8a7d63;background:rgba(138,125,99,0.10)}
/* ── Inbox-inject chip: "📨 N swarm-update arrived" between messages ──────── */
/*    Compact, monospace, amber-green to mark "the model just received async   */
/*    notifications before this turn". Same vocabulary as .sw-status-pill.     */
.sw-inbox-chip{display:inline-flex;align-items:center;gap:6px;margin:8px 0 6px;padding:4px 10px;border-radius:10px;font-family:'JetBrains Mono',monospace;font-size:11px;font-weight:500;color:#fbbf24;background:linear-gradient(135deg,rgba(251,191,36,0.06),rgba(74,222,128,0.04));border:1px solid rgba(251,191,36,0.18);letter-spacing:0.02em;animation:swInboxChipFlash 1.6s ease-out 1}
.sw-inbox-chip-icon{display:inline-flex;align-items:center;color:#fbbf24;flex-shrink:0;animation:swInboxChipBounce .9s ease-out 1}
.sw-inbox-chip-text{color:var(--text-secondary)}
.sw-inbox-chip-count{color:#4ade80;font-weight:700}
.sw-inbox-chip-ids{color:var(--text-tertiary);font-size:10px;margin-left:2px;opacity:0.85}
@keyframes swInboxChipFlash{0%{box-shadow:0 0 0 0 rgba(251,191,36,0.3)}40%{box-shadow:0 0 14px 0 rgba(251,191,36,0.18)}100%{box-shadow:0 0 0 0 rgba(251,191,36,0)}}
@keyframes swInboxChipBounce{0%{transform:translateY(-3px) scale(.7);opacity:0}60%{transform:translateY(1px) scale(1.05);opacity:1}100%{transform:translateY(0) scale(1);opacity:1}}
/* ── Async-swarm inbox-injection row (inside the ptool-panel timeline) ───── */
/*    A synthetic tool row marking where the model received N <swarm-update>  */
/*    sub-agent results as a user message before its next turn. Collapsible:  */
/*    expands to show the raw payloads the model actually saw.                */
.sw-inbox-row{margin:0;border:none}
.sw-inbox-row>.sw-inbox-row-header{cursor:pointer;list-style:none;display:flex;align-items:center;gap:8px}
.sw-inbox-row>.sw-inbox-row-header::-webkit-details-marker{display:none}
.sw-inbox-row .sw-inbox-row-ids{color:var(--text-tertiary);font-family:'JetBrains Mono',monospace;font-size:10px;opacity:0.85}
/* Collapse affordance: a caret appended after the row label (same convention as
   the convmeta / memory / todo blocks). The explicit .sw-inbox-row-chev span was
   removed so the far-right slot belongs unambiguously to the "模型原文" button. */
.sw-inbox-row>.sw-inbox-row-header .ptool-text::after{content:" ▸";font-size:10px;opacity:0.5}
.sw-inbox-row[open]>.sw-inbox-row-header .ptool-text::after{content:" ▾"}
/* "Who sent this" bubble — a conversation TITLE (via convTitleById), not a raw
   id. Reads like the peer-msg provenance banner so the sender is legible. It is
   a <button>: clicking jumps to the source conversation (delegated handler in
   tool_rounds.js). */
.sw-peer-from-group{display:inline-flex;align-items:center;gap:4px;flex-wrap:wrap;min-width:0}
.sw-peer-from-bubble{display:inline-flex;align-items:center;gap:5px;flex-shrink:1;min-width:0;max-width:420px;padding:1px 9px;border:1px solid rgba(130,170,255,.35);background:rgba(130,170,255,.09);border-radius:9px;font-size:11px;line-height:1.4;color:#82aaff;font-weight:600;font-family:inherit;cursor:pointer;transition:background .15s,border-color .15s}
.sw-peer-from-bubble:hover{background:rgba(130,170,255,.2);border-color:rgba(130,170,255,.65)}
.sw-peer-from-bubble svg{display:block;flex-shrink:0}
.sw-peer-from-bubble>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sw-peer-from-bubble .sw-peer-jump{opacity:.45;margin-left:1px}
.sw-peer-from-bubble:hover .sw-peer-jump{opacity:1}
/* Inside an expanded body card the bubble gets the full card width — the title
   must be readable end-to-end there, not ellipsized like the cramped header. */
.sw-peer-card-item .sw-peer-from-bubble{max-width:100%}
.sw-peer-from-more{flex-shrink:0;padding:1px 7px;border-radius:9px;font-size:10px;font-weight:700;color:var(--text-tertiary);background:rgba(130,170,255,.12)}
/* Inbox/peer/steer rows: the right-hand control group owns the right
   end of the header — exactly ONE owner, same as every other row. */
.sw-inbox-row>.sw-inbox-row-header .ptool-row-ctl{margin-left:auto}
.sw-inbox-row .sw-inbox-row-body{padding:6px 10px 8px 16px;display:flex;flex-direction:column;gap:8px}
.sw-inbox-row-empty{color:var(--text-tertiary);font-size:12px;font-style:italic}
/* ── Beautified sub-agent / peer update cards (human view) ──
   Replaces the old raw-<pre> XML dump. Clean field header + Markdown body. */
.sw-card{border:1px solid var(--border);border-left:2px solid rgba(251,191,36,0.5);border-radius:7px;padding:8px 11px;background:var(--bg-secondary);display:flex;flex-direction:column;gap:6px}
.sw-card-head{display:flex;align-items:center;gap:7px;flex-wrap:wrap}
.sw-card-agent{font-family:'JetBrains Mono',monospace;font-size:12px;font-weight:700;color:#fbbf24}
.sw-card-role{font-size:10.5px;font-weight:600;text-transform:uppercase;letter-spacing:0.03em;color:var(--text-tertiary);background:var(--bg-tertiary);padding:1px 7px;border-radius:7px}
.sw-card-status{margin-left:0}
.sw-card-meta{margin-left:auto;font-size:10.5px;color:var(--text-tertiary);font-family:'JetBrains Mono',monospace}
.sw-card-error{font-size:12px;line-height:1.5;color:var(--pb-red,#ef4444);background:color-mix(in srgb,var(--pb-red,#ef4444) 8%,transparent);border-radius:5px;padding:6px 9px;overflow-wrap:anywhere}
.sw-card-preview{font-size:12.5px;line-height:1.55;color:var(--text-primary);overflow-wrap:anywhere}
.sw-card-preview > :first-child{margin-top:0}
.sw-card-preview > :last-child{margin-bottom:0}
.sw-card-file{display:inline-flex;align-items:center;gap:5px;font-size:11px;color:var(--text-tertiary);font-family:'JetBrains Mono',monospace;overflow-wrap:anywhere}
.sw-card-file svg{display:block;flex-shrink:0}
.sw-card-raw-pre{margin:0;white-space:pre-wrap;word-break:break-word;font-family:'JetBrains Mono',monospace;font-size:11px;line-height:1.5;color:var(--text-secondary);background:rgba(255,255,255,0.02);border-radius:6px;padding:8px 10px;max-height:280px;overflow:auto}
.sw-card-rawonly .sw-card-raw-pre,.sw-peer-card-item{}
.sw-peer-card-item{border-left-color:var(--accent)}
[data-theme="light"] .sw-card-raw-pre{background:rgba(0,0,0,0.03)}
[data-theme="light"] .sw-peer-from-bubble{color:#3b5bdb;border-color:rgba(59,91,219,.35);background:rgba(59,91,219,.08)}
[data-theme="light"] .sw-peer-from-bubble:hover{background:rgba(59,91,219,.16);border-color:rgba(59,91,219,.55)}
[data-theme="light"] .sw-peer-from-more{background:rgba(59,91,219,.12)}
[data-theme="tofu"] .sw-card{background:#faf8f3;border-color:#e0d9c8;border-left-color:#d98c3f}
[data-theme="tofu"] .sw-card-agent{color:#b06d28}
[data-theme="tofu"] .sw-card-raw-pre{background:rgba(0,0,0,0.04);color:#3a342c}
[data-theme="tofu"] .sw-peer-from-bubble{color:#5b54c7;border-color:rgba(91,84,199,.35);background:rgba(91,84,199,.08)}
[data-theme="tofu"] .sw-peer-from-bubble:hover{background:rgba(91,84,199,.16);border-color:rgba(91,84,199,.55)}
[data-theme="tofu"] .sw-peer-from-more{background:rgba(91,84,199,.12)}
/* ── Async-only tool rounds: await_agents / get_agent_result mini-cards ───── */
/*    These are NOT swarm panels — they're regular tool rounds, but rendered   */
/*    with the swarm vocabulary (amber, monospace) so the user instantly       */
/*    recognizes "this is part of the swarm flow".                             */
@keyframes swarmIconBounce{0%,100%{transform:translateY(0)}50%{transform:translateY(-2px)}}
@keyframes agentPulse{0%,100%{opacity:0.6;transform:scale(0.9)}50%{opacity:1;transform:scale(1.1)}}
/* ── Live preview stream ── */
.sw-a-preview-live{border-color:rgba(251,191,36,0.15);background:rgba(251,191,36,0.03);position:relative}
.sw-typing-cursor{color:#fbbf24;font-weight:700;animation:blink 1s step-end infinite}
@keyframes blink{50%{opacity:0}}
/* ── Dependency tags ── */
.sw-a-deps{display:flex;flex-wrap:wrap;align-items:center;gap:4px;margin-bottom:6px;font-size:10px}
.sw-a-deps-label{color:var(--text-tertiary);font-weight:600;margin-right:2px}
.sw-dep-tag{display:inline-flex;align-items:center;gap:2px;padding:1px 6px;border-radius:4px;background:rgba(251,191,36,0.08);border:1px solid rgba(251,191,36,0.15);color:#fbbf24;font-family:'JetBrains Mono',monospace}
.sw-dep-tag.sw-dep-done{background:rgba(74,222,128,0.08);border-color:rgba(74,222,128,0.15);color:#4ade80}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}

/* ── App dialogs: themed confirm/alert/prompt (static/js/core/dialog.js) ── */
.app-dialog-overlay{position:fixed;inset:0;height:var(--vh100,100vh);background:rgba(0,0,0,0.55);backdrop-filter:blur(2px);z-index:10050;display:flex;align-items:center;justify-content:center;padding:20px;opacity:0;transition:opacity 0.16s ease}
.app-dialog-overlay.open{opacity:1}
.app-dialog-overlay.closing{opacity:0}
.app-dialog{background:var(--bg-secondary);border:1px solid var(--border-light);border-radius:var(--radius);padding:22px 24px 18px;width:400px;max-width:calc(100vw - 40px);box-shadow:0 16px 48px rgba(0,0,0,0.55);transform:translateY(8px) scale(0.98);opacity:0;transition:transform 0.18s cubic-bezier(0.2,1,0.3,1),opacity 0.18s ease}
.app-dialog-overlay.open .app-dialog{transform:translateY(0) scale(1);opacity:1}
.app-dialog-title{font-size:15px;font-weight:700;color:var(--text-primary);margin-bottom:10px;letter-spacing:0.01em}
.app-dialog-message{font-size:13.5px;line-height:1.6;color:var(--text-secondary);word-break:break-word}
.app-dialog-input{width:100%;margin-top:14px;padding:9px 12px;background:var(--bg-primary);border:1px solid var(--border);border-radius:var(--radius-xs);color:var(--text-primary);font-size:14px;font-family:inherit;outline:none;transition:border-color var(--transition)}
.app-dialog-input:focus{border-color:var(--accent)}
.app-dialog-actions{display:flex;gap:8px;justify-content:flex-end;margin-top:20px}
.app-dialog-btn{padding:8px 18px;border-radius:var(--radius-xs);font-size:13px;font-weight:600;font-family:inherit;cursor:pointer;border:1px solid transparent;transition:background var(--transition),border-color var(--transition),transform 0.1s}
.app-dialog-btn:active{transform:translateY(1px)}
.app-dialog-cancel{background:var(--bg-tertiary);color:var(--text-secondary);border-color:var(--border)}
.app-dialog-cancel:hover{background:var(--bg-hover);color:var(--text-primary)}
.app-dialog-cancel:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.app-dialog-ok{background:var(--accent);color:#fff}
.app-dialog-ok:hover{background:var(--accent-hover)}
.app-dialog-ok:focus-visible{outline:2px solid var(--accent-hover);outline-offset:2px}
.app-dialog-ok.is-danger{background:var(--error-text)}
.app-dialog-ok.is-danger:hover{background:#e05656}
/* Tofu theme: square neo-brutalist block to match the rest of the tofu UI */
[data-theme="tofu"] .app-dialog{background:#faf8f3;border:3px solid #1a1814;border-radius:var(--radius);box-shadow:var(--clay-sm)}
[data-theme="tofu"] .app-dialog-title{color:#1a1814;text-transform:uppercase;letter-spacing:0.04em}
[data-theme="tofu"] .app-dialog-message{color:#3a342c}
[data-theme="tofu"] .app-dialog-input{background:#fff;border:2px solid #1a1814;border-radius:var(--radius);color:#1a1814}
[data-theme="tofu"] .app-dialog-btn{border-radius:var(--radius);border:2px solid #1a1814;box-shadow:var(--clay-sm)}
[data-theme="tofu"] .app-dialog-btn:active{box-shadow:var(--clay-pressed);transform:translate(2px,2px)}

/* ═══ Multi-option chooser (showChoice) — used by the post-send inject-mode
   prompt. Each option is a full-width stacked button with an icon, a bold
   label and a muted subtitle. The accent option (steer) gets a teal edge. ═══ */
.app-dialog-choice{width:440px}
.app-dialog-choices{display:flex;flex-direction:column;gap:10px;margin-top:16px}
.app-choice-btn{display:flex;align-items:center;gap:13px;width:100%;text-align:left;padding:13px 15px;background:var(--bg-tertiary);border:1.5px solid var(--border);border-radius:var(--radius-sm);cursor:pointer;font-family:inherit;color:var(--text-primary);transition:border-color .16s,background .16s,transform .1s}
.app-choice-btn:hover{background:var(--bg-hover);border-color:var(--border-light)}
.app-choice-btn:active{transform:translateY(1px)}
.app-choice-btn:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.app-choice-icon{flex-shrink:0;width:34px;height:34px;border-radius:var(--radius-xs);background:var(--bg-primary);color:var(--text-tertiary);border:1px solid var(--border)}
.app-choice-text{display:flex;flex-direction:column;gap:2px;min-width:0}
.app-choice-label{font-size:13.5px;font-weight:700;letter-spacing:.01em}
.app-choice-sub{font-size:11.5px;line-height:1.45;color:var(--text-tertiary)}
/* Accent option (steer) — teal edge + icon glow so the mid-turn injection is
   visually distinct from the neutral queue default. */
.app-choice-btn.is-accent{border-color:rgba(45,212,191,0.45)}
.app-choice-btn.is-accent:hover{border-color:#2dd4bf;background:rgba(45,212,191,0.08)}
.app-choice-btn.is-accent .app-choice-icon{color:#2dd4bf;border-color:rgba(45,212,191,0.4);background:rgba(45,212,191,0.1)}
[data-theme="tofu"] .app-choice-btn{border:2px solid #1a1814;border-radius:var(--radius);box-shadow:var(--clay-sm)}
[data-theme="tofu"] .app-choice-btn:active{box-shadow:var(--clay-pressed);transform:translate(2px,2px)}
[data-theme="tofu"] .app-choice-icon{border:2px solid #1a1814;background:#fff}
[data-theme="tofu"] .app-choice-btn.is-accent{border-color:#0f766e}
[data-theme="tofu"] .app-choice-btn.is-accent .app-choice-icon{color:#0f766e;border-color:#0f766e}

/* ★ Perf: removed backdrop-filter:blur from preview modal and close button */
