.project-bar{display:flex;align-items:center;gap:8px;padding:8px 12px;margin-bottom:8px;background:rgba(245,158,11,0.06);border:1px solid rgba(245,158,11,0.2);border-radius:var(--radius-sm);font-size:12px;color:#f59e0b;animation:fadeIn .3s ease}.project-bar-icon{font-size:16px;flex-shrink:0}.project-bar-stats{font-family:'JetBrains Mono',monospace;font-size:10px;color:var(--text-tertiary);flex:1}.project-bar-btn{background:none;border:1px solid rgba(245,158,11,0.25);color:#f59e0b;cursor:pointer;padding:2px 8px;border-radius:4px;font-size:11px;font-family:inherit;transition:background-color .2s,color .2s}.project-bar-btn:hover{background:rgba(245,158,11,0.1)}.project-bar-btn:disabled{opacity:0.5;cursor:not-allowed}
