/* ── Daily Optimizer badge + panel ── */
.optimizer-badge{font-size:10px;font-weight:700;font-family:'JetBrains Mono',monospace;padding:3px 9px;border-radius:20px;white-space:nowrap;display:inline-flex;align-items:center;gap:5px;border:1px solid;animation:fadeIn .3s ease;background:rgba(52,211,153,0.12);color:#34d399;border-color:rgba(52,211,153,0.35);cursor:pointer;position:relative}
