.optimizer-panel{position:absolute;top:100%;right:0;margin-top:6px;width:380px;max-height:500px;overflow-y:auto;background:var(--panel-bg,#1e1e2e);border:1px solid var(--border);border-radius:var(--radius-md,8px);box-shadow:0 8px 32px rgba(0,0,0,0.4);z-index:1000;padding:10px;display:none;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;text-align:left;white-space:normal;font-weight:400;letter-spacing:normal;text-transform:none;cursor:auto}
