.opt-toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;font-size:11px;color:#cbd5e1}
.opt-toolbar-info{font-family:'JetBrains Mono',monospace;color:#e2e8f0}
.opt-run-btn{font-size:10px;padding:3px 10px;border-radius:4px;border:1px solid rgba(52,211,153,0.35);background:rgba(52,211,153,0.1);color:#34d399;cursor:pointer;font-weight:700}
.opt-run-btn:hover{background:rgba(52,211,153,0.2)}
.opt-run-btn:disabled{opacity:0.55;cursor:default}
.opt-section-title{font-size:11px;font-weight:700;color:#e2e8f0;text-transform:uppercase;letter-spacing:0.3px;margin:8px 0 4px;display:flex;align-items:center;gap:6px}
.opt-count{font-size:10px;background:rgba(148,163,184,0.25);color:#f1f5f9;padding:1px 7px;border-radius:10px;font-weight:700}
.opt-history-header{cursor:pointer;user-select:none;padding:4px 0;border-top:1px solid var(--border);margin-top:8px}
.opt-history-header:hover{color:#34d399}
.opt-row{padding:10px;border-radius:6px;margin-bottom:8px;background:rgba(30,41,59,0.55);border:1px solid rgba(52,211,153,0.25);border-left:3px solid #34d399}
.opt-row.opt-status-pending_review{background:rgba(30,41,59,0.55);border-color:rgba(250,204,21,0.3);border-left-color:#facc15}
.opt-row.opt-status-rejected{background:rgba(30,41,59,0.5);border-color:rgba(239,68,68,0.25);border-left-color:#ef4444;opacity:0.85}
.opt-row.opt-status-expired,.opt-row.opt-status-reverted{background:rgba(30,41,59,0.45);border-color:rgba(148,163,184,0.3);border-left-color:#94a3b8;opacity:0.85}
.opt-row-head{display:flex;align-items:center;gap:6px;font-size:12px;font-weight:600;color:#f1f5f9}
.opt-row-head b{color:#fff}
.opt-row-head .opt-action-summary span{color:#cbd5e1!important}
.opt-status-icon{flex-shrink:0}
.opt-action-summary{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#f1f5f9}
.opt-row-conf{font-size:10px;font-family:'JetBrains Mono',monospace;flex-shrink:0;font-weight:700}
