.opt-row-reason{font-size:11px;color:#fde68a;margin-top:4px;font-style:italic;background:rgba(15,23,42,0.55);padding:4px 8px;border-radius:4px;border-left:2px solid rgba(250,204,21,0.55);white-space:normal;overflow-wrap:anywhere;word-break:break-word}
