.opt-row-actions{margin-top:6px;display:flex;gap:4px}
.opt-btn{font-size:11px;padding:4px 12px;border-radius:4px;border:1px solid;cursor:pointer;font-weight:700}
.opt-btn-approve{border-color:rgba(34,197,94,0.4);background:rgba(34,197,94,0.1);color:#22c55e}
.opt-btn-approve:hover{background:rgba(34,197,94,0.2)}
