}
.apply-btn:hover {
  background: rgba(245, 158, 11, 0.25);
  color: #fbbf24;
  border-color: rgba(245, 158, 11, 0.5);
}
.apply-modal { max-width: 560px; }
.apply-preview {
  margin: 12px 0;
  border: 1px solid var(--border);
