}

/* ═══════════════════════════════════════════
   ★ Theme System
   ═══════════════════════════════════════════ */

/* ── Theme Picker UI ── */
.theme-picker{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
/* Degraded-section contract (settings/section_requires.js): a block whose JS
   dependency is missing hides its CONTROLS and shows a notice instead — never
   an empty box masquerading as a usable control. */
.settings-section-js-missing{display:none;font-size:12px;line-height:1.6;color:var(--text-secondary);
  background:var(--bg-tertiary);border:1px dashed var(--border-light);border-radius:var(--radius-sm);padding:8px 12px}
.settings-section-needs-js.degraded>.theme-picker,
.settings-section-needs-js.degraded>.settings-toggle-desc{display:none}
.settings-section-needs-js.degraded>.settings-section-js-missing{display:block}
.theme-option{display:flex;flex-direction:column;align-items:center;gap:5px;padding:8px 4px 6px;border:2px solid var(--border);border-radius:var(--radius-sm);cursor:pointer;transition:border-color .2s,background-color .2s,transform .2s,box-shadow .2s;background:var(--bg-tertiary)}
.theme-option:hover{border-color:var(--border-light);background:var(--bg-hover);transform:translateY(-1px)}
.theme-option.active{border-color:var(--accent);background:var(--accent-subtle);box-shadow:0 0 0 1px var(--accent)}
.theme-preview{width:100%;height:32px;border-radius:6px;border:1px solid rgba(128,128,128,0.15)}
.dark-preview{background:linear-gradient(135deg,#0a0a0c 0%,#1a1a21 40%,#6e56cf 100%)}
.light-preview{background:linear-gradient(135deg,#ffffff 0%,#f0f2f5 40%,#6366f1 100%)}
.tofu-preview{background:linear-gradient(135deg,#F5F3ED 0%,#E9E5DC 40%,#BB9572 100%)}
.theme-option span{font-size:12px;font-weight:600;color:var(--text-secondary)}
.theme-option.active span{color:var(--accent)}

.theme-option-label{display:inline-flex;align-items:center;gap:5px}
.theme-option-label svg{flex-shrink:0}
/* ── Theme picker: tofu overrides inside settings panel ── */
.settings-panel .theme-picker{gap:8px}
.settings-panel .theme-option{border:2px solid #1a1814;border-radius:0;background:#faf7f2;box-shadow:2px 2px 0 #1a1814;transition:transform .1s,box-shadow .1s,background .1s}
.settings-panel .theme-option:hover{border-color:#1a1814;background:#f0ead6;transform:translate(-1px,-1px);box-shadow:3px 3px 0 #1a1814}
.settings-panel .theme-option:active{transform:translate(2px,2px);box-shadow:0 0 0 #1a1814}
.settings-panel .theme-option.active{border-color:#1a1814;background:#d4a850;box-shadow:2px 2px 0 #1a1814;transform:translate(1px,1px)}
.settings-panel .theme-preview{border-radius:0;border:1.5px solid #1a1814}
.settings-panel .theme-option span{color:#3a342a;font-weight:700;font-size:11px;text-transform:uppercase;letter-spacing:.03em}
.settings-panel .theme-option.active span{color:#1a1814;font-weight:900}

/* ── Language Picker UI ── */
.lang-picker{display:flex;gap:8px;flex-wrap:wrap}
.lang-option{display:flex;align-items:center;gap:6px;padding:6px 14px;border:2px solid var(--border);border-radius:var(--radius-sm);cursor:pointer;transition:border-color .2s,background-color .2s;background:var(--bg-tertiary)}
.lang-option:hover{border-color:var(--border-light);background:var(--bg-hover)}
.lang-option.active{border-color:var(--accent);background:var(--accent-subtle);box-shadow:0 0 0 1px var(--accent)}
.lang-flag{font-size:16px;line-height:1}
.lang-label{font-size:12px;font-weight:600;color:var(--text-secondary)}
.lang-option.active .lang-label{color:var(--accent)}
/* ── Language picker: tofu overrides ── */
.settings-panel .lang-option{border:2px solid #1a1814;border-radius:0;background:#faf7f2;box-shadow:2px 2px 0 #1a1814;transition:transform .1s,box-shadow .1s,background .1s}
.settings-panel .lang-option:hover{border-color:#1a1814;background:#f0ead6;transform:translate(-1px,-1px);box-shadow:3px 3px 0 #1a1814}
.settings-panel .lang-option:active{transform:translate(2px,2px);box-shadow:0 0 0 #1a1814}
.settings-panel .lang-option.active{border-color:#1a1814;background:#d4a850;box-shadow:2px 2px 0 #1a1814;transform:translate(1px,1px)}
.settings-panel .lang-label{color:#3a342a;font-weight:700}
.settings-panel .lang-option.active .lang-label{color:#1a1814;font-weight:900}

/* ═══════════════════════════════════════════
   ★ Light Theme
   ═══════════════════════════════════════════ */
[data-theme="light"]{
  --bg-primary:#f4f2ed;
  --bg-secondary:#eceae4;
  --bg-tertiary:#e3e1da;
  --bg-hover:#d9d7cf;
  --bg-active:#d0cdc4;
  --border:#c2beb3;
  --border-light:#ada89c;
  --text-primary:#272732;
  --text-secondary:#504f5b;
  --text-tertiary:#868490;
  --accent:#6366f1;
  --accent-hover:#4f46e5;
  --accent-subtle:rgba(99,102,241,0.09);
  --thinking-bg:rgba(174,118,0,0.06);
  --thinking-border:rgba(174,118,0,0.22);
  --thinking-text:#96620e;
  --error-bg:rgba(200,50,50,0.06);
  --error-border:rgba(200,50,50,0.18);
  --error-text:#b82020;
  --user-bubble:#e2def0;
  --shadow:0 1px 4px rgba(0,0,0,0.06),0 1px 2px rgba(0,0,0,0.03);
  --search-blue:#4068b8;
  --search-cyan:#1990a8;
  --search-purple:#7a5cbd;
  --fetch-green:#1f7a5c;
  --fetch-teal:#28857a
}

/* Light: structural overrides */
[data-theme="light"] .welcome-icon{background:transparent;box-shadow:none}
/* 字标在 light 下必须加深 —— 共用的奶油-琥珀金系是为深底调的,落到 light 的近白侧栏
   (#f4f2ed)与白底欢迎屏上实测只有 1.00–2.35:1 —— 其中「o」的起点 #fdf2d7 在白底
   上是 1.00:1,字面意义上看不见。此处只换明度、不换色相(仍是琥珀/陶土族),最差
   3.26:1、多数 >4.5:1,四字的明暗层次与深底保持一致。
   ★ 必须成对写两面(.sidebar-brand-* 与 .tofu-brand-*):只盖侧栏的单边覆盖正是之前
   light 里那四条靓蓝渐变造成两套字标的原因;守卫按三主题钉死这一点。 */
[data-theme="light"] .sidebar-brand-t,
[data-theme="light"] .welcome h2.tofu-brand .tofu-brand-t{background-image:linear-gradient(135deg,#A06C1C,#85560F)}
[data-theme="light"] .sidebar-brand-o,
[data-theme="light"] .welcome h2.tofu-brand .tofu-brand-o1{background-image:linear-gradient(135deg,#B07C24,#96661A)}
[data-theme="light"] .sidebar-brand-f,
[data-theme="light"] .welcome h2.tofu-brand .tofu-brand-f{background-image:linear-gradient(135deg,#85560F,#6B430A)}
[data-theme="light"] .sidebar-brand-u,
[data-theme="light"] .welcome h2.tofu-brand .tofu-brand-u{background-image:linear-gradient(135deg,#A06C1C,#784C0D)}
[data-theme="light"] .avatar.assistant{background:linear-gradient(135deg,#6366f1,#818cf8)}
[data-theme="light"] .message-avatar img,[data-theme="light"] .message-avatar svg{filter:none}
[data-theme="light"] .turn-nav{background:rgba(244,242,237,0.93);border-color:var(--border)}
[data-theme="light"] .turn-dot-writes{border-color:rgba(16,185,129,0.4);color:#059669;background:rgba(16,185,129,0.08)}
[data-theme="light"] .turn-dot-writes:hover{border-color:#059669;color:#059669;background:rgba(16,185,129,0.15)}
[data-theme="light"] .turn-dot-writes.active{background:#059669;color:#fff;border-color:#059669}
[data-theme="light"] .modal-overlay{background:rgba(30,28,20,0.18)}
[data-theme="light"] #previewModal{background:rgba(0,0,0,0.55)}

[data-theme="light"] .preview-close-btn{background:rgba(255,255,255,0.25)}[data-theme="light"] .preview-close-btn:hover{background:rgba(255,255,255,0.4)}
[data-theme="light"] .drop-overlay{background:rgba(244,242,237,0.92)}
[data-theme="light"] .debug-panel{background:rgba(244,242,237,0.97);color:#505060;border-color:var(--border)}
[data-theme="light"] .debug-msg-block{border-color:rgba(0,0,0,0.12)}
[data-theme="light"] .debug-msg-body pre{color:#333}
/* Syntax + role colours are re-picked per theme, never inherited: the dark
   palette is tuned for a #111 ground and lands at 1.7-4.3:1 on paper. Every
   value below is >=4.5:1 on --bg-secondary (#eceae4), measured. */
[data-theme="light"] .debug-msg-body pre .debug-key{color:#0b4f9e}[data-theme="light"] .debug-msg-body pre .debug-str{color:#1b5e20}[data-theme="light"] .debug-msg-body pre .debug-num{color:#9c3200}[data-theme="light"] .debug-msg-body pre .debug-null{color:#00606b}
/* The ROLE labels had no light override at all — the dark #4fc3f7/#81c784/
   #ce93d8 family measured 1.67-1.99:1 here, i.e. barely legible. */
[data-theme="light"] .debug-msg-header .role-system{color:#9a5b00}
[data-theme="light"] .debug-msg-header .role-user{color:#0b5c8a}
[data-theme="light"] .debug-msg-header .role-assistant{color:#1f6b3a}
[data-theme="light"] .debug-msg-header .role-tool{color:#6b3fa0}
[data-theme="light"] .debug-msg-header .role-tools{color:#8a4b00}
