[data-theme="tofu"] .md-content td,[data-theme="tofu"] .md-content th{border-color:#D8D1C0}
[data-theme="tofu"] .md-content tr:nth-child(even) td{background:rgba(196,149,106,0.03)}

/* ── Text selection — warm amber highlight ── */
[data-theme="tofu"] ::selection{
