  box-shadow:none
}

/* ── Model selector — quiet token pill ── */
[data-theme="tofu"] .preset-toggle{
  border-radius:var(--radius-xs);
  /* Item 2 — frosted-glass kinship with the project bar's pills: translucent
     tofu-cream fill + backdrop blur so the toolbar reads as the SAME surface as
     the bar (the scene wash shows through between pills). */
  background:linear-gradient(180deg, rgba(250,248,242,0.62) 0%, rgba(240,237,228,0.5) 100%);
  -webkit-backdrop-filter:blur(6px) saturate(1.05);
  backdrop-filter:blur(6px) saturate(1.05);
  border:1px solid var(--border);
  color:var(--text-secondary);
  box-shadow:none;
  clip-path:none;
  image-rendering:auto;
  transition:background 0.18s ease,color 0.18s ease,border-color 0.18s ease
}
[data-theme="tofu"] .preset-toggle:hover{
