/* Brand color overrides — slim colored bottom accent */
[data-theme="tofu"] .preset-toggle[data-brand="claude"]{color:#9A6520;box-shadow:inset 0 -2px 0 rgba(217,119,6,0.35)}
[data-theme="tofu"] .preset-toggle[data-brand="openai"]{color:#2D7A4A;box-shadow:inset 0 -2px 0 rgba(16,163,127,0.3)}
[data-theme="tofu"] .preset-toggle[data-brand="gemini"]{color:#3A6898;box-shadow:inset 0 -2px 0 rgba(66,133,244,0.3)}
[data-theme="tofu"] .preset-toggle[data-brand="deepseek"]{color:#4A5A92;box-shadow:0 2px 0 rgba(154,144,122,0.4), inset 0 -2px 0 rgba(77,107,254,0.3)}
[data-theme="tofu"] .preset-toggle .ps-label{
