}
.conv-ref-chip-icon{
  font-size:14px;line-height:1;
  color:#c792ea;
  flex-shrink:0;
}
.conv-ref-chip-info{
  display:flex;flex-direction:column;gap:1px;min-width:0;overflow:hidden;
}
.conv-ref-chip-title{
  font-size:12px;font-weight:500;color:var(--text-primary);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.conv-ref-chip-id{
  font-size:10px;color:var(--text-tertiary);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.conv-ref-chip-remove{
  background:none;border:none;color:var(--text-tertiary);cursor:pointer;
  padding:2px 4px;font-size:14px;line-height:1;transition:color .15s, background .15s;flex-shrink:0;
  border-radius:4px;margin-left:auto;
}
.conv-ref-chip-remove:hover{color:#c792ea;background:rgba(199,146,234,.15)}

/* ── Conversation Reference badge (in chat messages) ── */
.conv-ref-badge{
  border-color:rgba(199,146,234,.35) !important;
  background:rgba(199,146,234,.06) !important;
}
.conv-ref-badge:hover{border-color:#c792ea !important}
.conv-ref-badge .reply-quote-badge-icon{filter:none}

/* ── Peer-message provenance banner (chat_render.js) ── */
/* An advisory turn injected by a sibling conversation of the same project. */
.peer-msg-banner{
  display:inline-flex;align-items:center;gap:6px;
  margin:0 0 8px 0;padding:4px 10px;
  border:1px solid rgba(130,170,255,.35);
  background:rgba(130,170,255,.08);
  border-radius:8px;font-size:12px;line-height:1.3;
  color:var(--text-secondary, #9aa4b2);
}
.peer-msg-banner .peer-msg-icon{display:inline-flex;color:#82aaff}
.peer-msg-banner .peer-msg-from{color:#82aaff;font-weight:600}
/* Operator nudge (from the Team panel) — distinct from an agent peer note. */
.peer-msg-banner.peer-msg-banner-operator{border-color:rgba(126,231,135,.4);background:rgba(126,231,135,.09)}
.peer-msg-banner.peer-msg-banner-operator .peer-msg-icon,
.peer-msg-banner.peer-msg-banner-operator .peer-msg-from{color:#7ee787}

/* ── Brain-dispatch provenance card (chat_render.js _renderBrainDispatchCard)
   A Project-Brain kickoff turn: the card carries WHICH epic / WHO posted it /
   HOW+WHY it was routed here, so the raw English instruction wall can stay
   collapsed behind .brain-kickoff-raw. Brain-purple accent (same family as
   the conv-ref badge) — distinct from the peer banner's blue. */
.brain-dispatch-card{
  margin:0 0 10px 0;padding:10px 14px 11px;
  border:1px solid rgba(199,146,234,.35);
  background:linear-gradient(135deg, rgba(199,146,234,.10), rgba(130,170,255,.05));
  border-radius:10px;font-size:12.5px;line-height:1.5;
  color:var(--text-secondary, #9aa4b2);
}
.brain-dispatch-card .bdc-head{
  display:flex;align-items:center;gap:6px;margin-bottom:4px;
  font-size:11.5px;font-weight:600;letter-spacing:.03em;color:#c792ea;
}
.brain-dispatch-card .bdc-icon{display:inline-flex}
.brain-dispatch-card .bdc-epic-id{
  margin-left:auto;font-family:var(--font-mono, ui-monospace, monospace);
  font-size:11px;font-weight:400;color:var(--text-tertiary, #6b7280);
}
.brain-dispatch-card .bdc-answered{
  display:inline-flex;align-items:center;padding:1px 8px;border-radius:999px;
  background:rgba(126,231,135,.12);border:1px solid rgba(126,231,135,.35);
  color:#7ee787;font-size:11px;font-weight:600;letter-spacing:0;
}
.brain-dispatch-card .bdc-epic-title{
  font-size:13px;font-weight:600;color:var(--text-primary, #e6e9ee);
  cursor:pointer;line-height:1.4;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;
}
.brain-dispatch-card .bdc-epic-title:hover{color:#c792ea;text-decoration:underline}
.brain-dispatch-card .bdc-meta{
  display:flex;flex-wrap:wrap;gap:3px 16px;margin-top:7px;font-size:12px;
}
.brain-dispatch-card .bdc-meta-label{
  color:var(--text-tertiary, #6b7280);margin-right:5px;
}
.brain-dispatch-card .bdc-conv-link{
  color:#82aaff;font-weight:600;text-decoration:none;
}
.brain-dispatch-card .bdc-conv-link:hover{text-decoration:underline}
.brain-dispatch-card .bdc-this{font-weight:600;color:var(--text-primary, #e6e9ee)}
/* The raw engine kickoff text — collapsed by default; the card above is the
   human-facing summary. Dashed frame reads as "machinery, not prose". */
.brain-kickoff-raw{
  margin:0 0 8px 0;padding:5px 12px;
  border:1px dashed var(--border, #333);border-radius:8px;
}
.brain-kickoff-raw>summary{
  cursor:pointer;padding:2px 0;user-select:none;
  font-size:12px;color:var(--text-tertiary, #6b7280);
}
.brain-kickoff-raw>summary:hover{color:var(--text-secondary, #9aa4b2)}
.brain-kickoff-raw[open]>summary{margin-bottom:6px}
.brain-kickoff-raw .user-content{font-size:12px;opacity:.85;white-space:pre-wrap}

/* ── Conversation Reference Picker Popover ── */
.conv-ref-picker{
  position:fixed;z-index:10000;
  display:flex;flex-direction:column;
  background:var(--bg-secondary);
  border:1px solid var(--border);
  border-radius:var(--radius-md, 12px);
  box-shadow:0 12px 40px rgba(0,0,0,.5), 0 0 0 1px rgba(199,146,234,.15);
  overflow:hidden;
  animation:convRefPickerIn .18s ease-out;
}
@keyframes convRefPickerIn{
  from{opacity:0;transform:translateY(8px) scale(.97)}
  to{opacity:1;transform:translateY(0) scale(1)}
}
.conv-ref-picker-header{
  display:flex;align-items:center;justify-content:space-between;
  padding:12px 14px 8px;
  border-bottom:1px solid var(--border);
}
.conv-ref-picker-title{
  font-size:13px;font-weight:600;color:#c792ea;
}
.conv-ref-picker-close{
  background:none;border:none;color:var(--text-tertiary);
  font-size:20px;line-height:1;cursor:pointer;padding:0 4px;
  transition:color .15s;
}
.conv-ref-picker-close:hover{color:var(--text-primary)}
.conv-ref-picker-search{
  padding:8px 12px;
}
.conv-ref-picker-search input{
  width:100%;box-sizing:border-box;
  padding:8px 12px;
  background:var(--bg-primary);
  border:1px solid var(--border);border-radius:var(--radius-sm, 8px);
  color:var(--text-primary);font-size:13px;
  outline:none;transition:border-color .2s;
}
.conv-ref-picker-search input:focus{
  border-color:#c792ea;
  box-shadow:0 0 0 2px rgba(199,146,234,.15);
}
.conv-ref-picker-search input::placeholder{color:var(--text-tertiary)}
.conv-ref-picker-list{
  flex:1;overflow-y:auto;padding:4px 6px 8px;
  max-height:280px;
}
.conv-ref-picker-item{
  padding:9px 10px;margin:2px 0;
  border-radius:var(--radius-sm, 8px);
  cursor:pointer;transition:background .15s;
}
.conv-ref-picker-item:hover{background:rgba(199,146,234,.08)}
.conv-ref-picker-item-main{
  display:flex;align-items:center;gap:6px;
}
.conv-ref-picker-item-title{
  font-size:13px;font-weight:500;color:var(--text-primary);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  flex:1;min-width:0;
}
.conv-ref-picker-item-check{
  font-size:13px;color:#c792ea;font-weight:700;flex-shrink:0;
}
.conv-ref-picker-item-meta{
  display:flex;gap:4px;margin-top:3px;
  font-size:11px;color:var(--text-tertiary);
}
.conv-ref-picker-empty{
  padding:24px 12px;text-align:center;
  font-size:13px;color:var(--text-tertiary);
}

/* Scrollbar for picker list */
.conv-ref-picker-list::-webkit-scrollbar{width:4px}
.conv-ref-picker-list::-webkit-scrollbar-thumb{background:var(--border);border-radius:2px}
.conv-ref-picker-list::-webkit-scrollbar-thumb:hover{background:var(--text-tertiary)}

/* old .edit-reply-quote removed — replaced by .edit-rq-chip */

/* ── Inline branch node (anchored inside content) ── */
.branch-node.inline{
  display:flex;font-size:12px;padding:5px 12px;margin:0;
