.cd-content-blocks { display: flex; flex-direction: column; gap: 4px; }

.cd-toolcall {
  margin: 6px 0;
  padding: 0;
}
.cd-toolcall-name {
  font-family: 'JetBrains Mono', 'SF Mono', monospace;
  font-size: 11px;
  color: #22d3ee;
  margin: 4px 0;
