  font-size: 10px;
  opacity: 0.7;
}

.cd-image-block {
  margin: 4px 0;
  padding: 8px 10px;
  background: rgba(0, 0, 0, 0.18);
  border: 1px dashed var(--border-subtle, rgba(255,255,255,0.1));
  border-radius: 4px;
}
