  font-size: 11px;
  color: var(--text-tertiary);
  margin-bottom: 6px;
  font-family: 'JetBrains Mono', 'SF Mono', monospace;
}
.cd-image-placeholder button {
  background: transparent;
  border: 1px solid var(--border-subtle, rgba(255,255,255,0.12));
  color: var(--accent);
  padding: 4px 10px;
  font-size: 11px;
  border-radius: 3px;
  cursor: pointer;
  transition: all 120ms ease;
}
.cd-image-placeholder button:hover {
  background: color-mix(in srgb, var(--accent) 15%, transparent);
  color: var(--text-primary);
}
.cd-image-placeholder img {
  max-width: 100%;
  max-height: 360px;
  border-radius: 3px;
  display: block;
}

.cd-thinking {
  margin-top: 6px;
  padding: 6px 10px;
  background: rgba(0, 0, 0, 0.15);
  border: 1px solid var(--border-subtle, rgba(255,255,255,0.06));
  border-radius: 3px;
}
.cd-thinking summary {
  cursor: pointer;
  font-size: 10.5px;
  color: var(--text-tertiary);
  font-family: 'JetBrains Mono', 'SF Mono', monospace;
}
.cd-thinking pre { margin: 6px 0 0; }

/* History tab */
.compaction-history-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.cd-history-item {
  padding: 10px 12px;
  border: 1px solid var(--border-subtle, rgba(255,255,255,0.08));
  border-radius: 4px;
  background: var(--bg-elevated, rgba(255,255,255,0.02));
  cursor: pointer;
  transition: all 120ms ease;
}
.cd-history-item:hover {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border-subtle, rgba(255,255,255,0.08)));
