  font-size: 11px;
  color: #fbbf24;
  font-style: italic;
}

/* Footer */
.compaction-drawer-footer {
  flex: 0 0 auto;
  display: flex;
  gap: 8px;
  padding: 12px 22px;
  border-top: 1px solid var(--border-subtle, rgba(255,255,255,0.08));
