/* Small screens — full-width drawer */
@media (max-width: 720px) {
  .compaction-drawer-panel {
    width: 100vw;
    border-left: none;
  }
  .cd-meta-grid { grid-template-columns: 1fr; }
  .cd-receipt-groups { grid-template-columns: 1fr; }
}

/* ═══════════════════════════════════════════════════════════════════
   Context indicator — "Liquid Bubble".

   Concept: a 28×28 SOLID circular vessel filled with liquid that
   rises from the bottom as context grows.  Glass rim stroke + a
   static upper-left shine sell "vessel"; a thin bright meniscus
   along the wave top sells "real liquid surface".  The wave geometry
   is static — only the liquid LEVEL (vertical translate of the wave
   group) changes on actual percentage updates.

   This explicitly walks back from the prior "halo capsule".  At
   chip-size, a thin line capsule reads as anonymous; a solid round
   vessel filled with a substance reads as ownable, alive, and
   uniquely Tofu.

   Color zones (uniform across themes — only the chrome differs):
   - ok    (<60 %) : theme-dependent calm tone (indigo / blue / green)
   - warn  (≥60 %) : amber  #d99e3a
   - hot   (≥82 %) : orange #d97a3a
   - crit  (≥95 %) : red    #c44747

   Anti-flicker invariants (mirror context-bar.js header):
   - The ONLY thing that ever animates is the liquid LEVEL on actual
     value change, via a CSS transition on the wave group's
     `transform`.  The wave geometry itself never moves.  Counter
     "land" cues are one-shot 1.4 s class toggles.
   ═══════════════════════════════════════════════════════════════════ */

.ctx-health-bar{
  /* In-flow inside #convStatusStrip (context-bar.js _ensureBar prepends it).
   * It used to be absolute at left:18px/top:50% of .chat-wrapper — which
   * genuinely overlapped the message column below a ~1420px pane — so the
   * anchoring is gone, not re-tuned. */
  flex:0 0 auto;
  display:inline-flex;
  align-items:center;
  gap:9px;
  padding:5px 11px 5px 5px;
  border-radius:999px;
  user-select:none;
  cursor:default;
  --ctx-zone-color:var(--text-tertiary);
  --ctx-zone-color-warn:#d99e3a;
  --ctx-zone-color-hot: #d97a3a;
  --ctx-zone-color-crit:#c44747;
  /* Subtle one-shot entry. */
  opacity:0;
  animation:ctx-fade-in .35s ease-out forwards;
}
@keyframes ctx-fade-in{ to{ opacity:1; } }
.ctx-health-bar[data-zone="warn"]{ --ctx-zone-color:var(--ctx-zone-color-warn); }
.ctx-health-bar[data-zone="hot"] { --ctx-zone-color:var(--ctx-zone-color-hot);  }
.ctx-health-bar[data-zone="crit"]{ --ctx-zone-color:var(--ctx-zone-color-crit); }

/* The bubble host — a 28×28 box that just positions the inline SVG
 * and the counter badge.  No background of its own; the SVG carries
 * all the visuals. */
.ctx-bar-bubble{
  position:relative;
  width:28px;
  height:28px;
  flex:0 0 auto;
}
.ctx-bubble-svg{ display:block; }

/* ── In-progress spinner (manual /compact) ──
 * A CSS-drawn rotating ring overlaid on the bubble while a manual compaction
 * is running. Keyed on the chip's `data-compacting` attribute (set by
 * context-bar.js `_setCompacting`). This REPLACES the old optimistic "正在压缩"
 * toast — progress lives on the chip, so it never stacks with the terminal
 * toast. No emoji / font glyph (§3.4): the ring is a conic-gradient mask. */
.ctx-health-bar[data-compacting] .ctx-bar-bubble::after{
  content:"";
  position:absolute;
  inset:-2px;
  border-radius:50%;
  background:conic-gradient(var(--accent) 0deg 90deg, transparent 90deg 360deg);
  -webkit-mask:radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 3px));
          mask:radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 3px));
  animation:ctxCompactSpin 0.8s linear infinite;
  pointer-events:none;
  z-index:2;
}
@keyframes ctxCompactSpin{ to{ transform:rotate(360deg); } }
@media (prefers-reduced-motion: reduce){
  .ctx-health-bar[data-compacting] .ctx-bar-bubble::after{ animation:none; opacity:0.7; }
}

/* Empty vessel base — the cream/dark "container color" that shows
 * through above the liquid line.  Intentionally subtle so the
 * liquid (.ctx-bubble-wave) carries the visual weight. */
.ctx-bubble-bg{
  fill:var(--ctx-vessel-bg, rgba(255,255,255,0.06));
  stroke:none;
}

/* The liquid body — filled by an SVG linearGradient defined inline
 * (id randomized per chip).  The gradient goes from a lighter "near
 * surface" tint at the top to the saturated zone color at the base —
 * this depth gradient is what really makes a still liquid look real
 * (more than any wave geometry would).  The two stop classes below
 * set the actual stop colors. */
.ctx-bubble-wave{
  /* `fill` set inline on the element (`fill="url(#...)"`); the
   * gradient stops below provide the actual colors. */
}
.ctx-bubble-grad-top{
  /* Brighter near-surface tint — keeps a hint of the zone color so
   * warn/hot/crit still warm the top, but mixed toward white. */
  stop-color:color-mix(in srgb, var(--ctx-zone-color) 55%, var(--ctx-liquid-light, #fff));
}
.ctx-bubble-grad-bot{
  /* Deep base color — the zone color slightly darkened.  Gives
   * "depth" to the liquid the way real liquid bodies look darker
   * the further you look down through them. */
  stop-color:color-mix(in srgb, var(--ctx-zone-color) 90%, #000);
}

/* The wave group — the only thing that ever moves.  Its transform
 * attribute is set by the JS to translate(0 Y) where Y is the
 * liquid surface position in viewBox units.  CSS transition on
 * `transform` smooths the level rise/fall. */
.ctx-bubble-wave-group{
  transition:transform .55s cubic-bezier(.2,.85,.25,1.05);
}

/* Soft meniscus highlight — a thin near-white stroke along the
 * surface.  Kept very subtle (low opacity, narrow stroke) so it
 * reads as "light reflecting on the surface" rather than a drawn
 * line.  No drop-shadow filter — that read as artificial.
 * The class names ".ctx-bubble-meniscus" and ".ctx-bubble-wave" are
 * preserved for back-compat; the SHAPE is now a still meniscus, not
 * a sine wave. */
.ctx-bubble-meniscus{
  fill:none;
  stroke:var(--ctx-meniscus, color-mix(in srgb, #ffffff 80%, var(--ctx-zone-color)));
  stroke-width:.45;
  stroke-linecap:round;
  stroke-linejoin:round;
  opacity:.85;
}

/* Inner glass shadow — a soft dark ring just inside the rim,
 * clipped to the bubble interior.  Provides the cue that the glass
 * has wall thickness without adding a second outer shadow. */
.ctx-bubble-inner-shadow{
  fill:none;
  stroke:var(--ctx-inner-shadow, rgba(0,0,0,0.18));
  stroke-width:1.6;
  /* Hand-tuned: stroke is half-inside, half-outside the radius,
   * so a slightly smaller r keeps the shadow purely on the inside
   * edge of the rim.  Set via attribute on the element instead. */
}

/* Glass rim — drawn on top of the clipped liquid so it always reads
 * as the bubble outline regardless of fill level. */
.ctx-bubble-rim{
  fill:none;
  stroke:var(--ctx-rim, rgba(0,0,0,0.45));
  stroke-width:1;
}

/* Upper-left shine — a single arc that sells "glass vessel".
 * Static; never animates. */
.ctx-bubble-shine{
  fill:none;
  stroke:var(--ctx-shine, rgba(255,255,255,0.45));
  stroke-width:1.1;
  stroke-linecap:round;
