}

/* Hide every legacy bit we no longer use (kept as a safety net for
 * any cached HTML / third-party script that still references them). */

/* Text block: % primary, "1M" cap secondary.  Dot separator between. */
.ctx-bar-pct{
  font-family:'JetBrains Mono', ui-monospace, monospace;
  font-size:12px;
  font-weight:600;
  color:var(--text-secondary);
  letter-spacing:0.01em;
  line-height:1.05;
  font-variant-numeric:tabular-nums;
  transition:color .25s ease;
}
.ctx-bar-cap{
  font-family:'JetBrains Mono', ui-monospace, monospace;
  font-size:9px;
  color:var(--text-tertiary);
  line-height:1.05;
  font-variant-numeric:tabular-nums;
}
.ctx-health-bar > .ctx-bar-pct{ margin-left:1px; }
.ctx-health-bar > .ctx-bar-cap{
  opacity:0.55;
  margin-left:6px;
  position:relative;
  padding-left:7px;
  transition:opacity .18s ease;
}
.ctx-health-bar > .ctx-bar-cap::before{
  content:"";
  position:absolute;
  left:0; top:50%;
  width:2px; height:2px;
  border-radius:50%;
  background:currentColor;
  opacity:.55;
  transform:translateY(-50%);
}
.ctx-health-bar:hover > .ctx-bar-cap{ opacity:1; }
.ctx-health-bar[data-zone="warn"] .ctx-bar-pct,
.ctx-health-bar[data-zone="hot"]  .ctx-bar-pct,
.ctx-health-bar[data-zone="crit"] .ctx-bar-pct{ color:var(--ctx-zone-color); }

